-- Canonical initial schema. Startup uses SQLAlchemy metadata.create_all for this small project.
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY,email VARCHAR(120) UNIQUE NOT NULL,role VARCHAR(20) NOT NULL,password_hash VARCHAR(200) NOT NULL);
CREATE TABLE IF NOT EXISTS students (id SERIAL PRIMARY KEY,code VARCHAR(50) UNIQUE NOT NULL,name VARCHAR(80) NOT NULL,campus VARCHAR(50) NOT NULL,"group" VARCHAR(20) NOT NULL,score FLOAT,absent BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS plans (id SERIAL PRIMARY KEY,title VARCHAR(120) UNIQUE NOT NULL,campus VARCHAR(50) NOT NULL,exclude_absent BOOLEAN NOT NULL,description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports (id SERIAL PRIMARY KEY,plan_id INTEGER NOT NULL REFERENCES plans(id),status VARCHAR(20) NOT NULL,result JSON,error TEXT NOT NULL,conclusion TEXT NOT NULL,published BOOLEAN NOT NULL,supplement_snapshot JSON,created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS supplement_draws (id SERIAL PRIMARY KEY,plan_id INTEGER NOT NULL UNIQUE REFERENCES plans(id),status VARCHAR(20) NOT NULL,seed VARCHAR(64) NOT NULL,design JSON NOT NULL,checksum VARCHAR(64) NOT NULL,created_by VARCHAR(120) NOT NULL,created_at VARCHAR(40) NOT NULL,issued_at VARCHAR(40));
CREATE TABLE IF NOT EXISTS supplement_samples (id SERIAL PRIMARY KEY,draw_id INTEGER NOT NULL REFERENCES supplement_draws(id),plan_id INTEGER NOT NULL REFERENCES plans(id),student_id INTEGER NOT NULL REFERENCES students(id),code VARCHAR(50) NOT NULL,name VARCHAR(80) NOT NULL,campus VARCHAR(50) NOT NULL,"group" VARCHAR(20) NOT NULL,stratum VARCHAR(120) NOT NULL,inclusion_probability FLOAT NOT NULL,selection_rank INTEGER NOT NULL,outcome VARCHAR(20) NOT NULL,retest_score FLOAT,responded_at VARCHAR(40),response_by VARCHAR(120) NOT NULL,response_version INTEGER NOT NULL,created_at VARCHAR(40) NOT NULL,UNIQUE(plan_id,student_id),UNIQUE(draw_id,student_id));
CREATE TABLE IF NOT EXISTS supplement_responses (id SERIAL PRIMARY KEY,sample_id INTEGER NOT NULL REFERENCES supplement_samples(id),outcome VARCHAR(20) NOT NULL,retest_score FLOAT,note TEXT NOT NULL,actor VARCHAR(120) NOT NULL,created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs (id SERIAL PRIMARY KEY,actor VARCHAR(120) NOT NULL,action VARCHAR(200) NOT NULL,status INTEGER NOT NULL,created_at VARCHAR(40) NOT NULL);
